insert into quiz_questions (id,quiz_id,seq,prompt,options,correct_index,explanation,marks) values ('quiz-sci6-food-q1','quiz-sci6-food',1,'Which nutrient is the main source of energy for our body?',ARRAY['Proteins','Carbohydrates','Vitamins','Water']::text[],1,'Carbohydrates are the body’s primary energy source.',1) on conflict (id) do nothing;
insert into quiz_questions (id,quiz_id,seq,prompt,options,correct_index,explanation,marks) values ('quiz-sci6-food-q2','quiz-sci6-food',2,'Scurvy is caused by the deficiency of which vitamin?',ARRAY['Vitamin A','Vitamin C','Vitamin D','Vitamin K']::text[],1,'Vitamin C deficiency causes scurvy (bleeding gums).',1) on conflict (id) do nothing;
insert into quiz_questions (id,quiz_id,seq,prompt,options,correct_index,explanation,marks) values ('quiz-sci6-food-q3','quiz-sci6-food',3,'Which of these is a body-building food (rich in protein)?',ARRAY['Rice','Butter','Pulses','Sugar']::text[],2,'Pulses (dals), eggs and milk are rich in proteins.',1) on conflict (id) do nothing;
