insert into quiz_questions (id,quiz_id,seq,prompt,options,correct_index,explanation,marks) values ('quiz-math6-int-q1','quiz-math6-int',1,'The additive inverse of −7 is:',ARRAY['7','−7','0','1/7']::text[],0,'The additive inverse of −7 is +7 because −7 + 7 = 0.',1) on conflict (id) do nothing;
