-- ============================================================================
-- Wellspire SMS — Student learning: CBSE syllabus, study material & tests
-- Migration 0007. Idempotent (IF NOT EXISTS / ON CONFLICT DO NOTHING).
-- ============================================================================

create table if not exists syllabus (
  id text primary key,
  school_id uuid references schools(id) on delete cascade,
  grade text not null, subject text not null, chapter_no int not null,
  title text not null, topics text[] default '{}', term text, board text default 'CBSE',
  created_at timestamptz default now(), updated_at timestamptz default now()
);
create table if not exists study_materials (
  id text primary key,
  school_id uuid references schools(id) on delete cascade,
  grade text not null, subject text not null, title text not null,
  type text not null, description text, url text, minutes int,
  created_at timestamptz default now(), updated_at timestamptz default now()
);
create table if not exists quizzes (
  id text primary key,
  school_id uuid references schools(id) on delete cascade,
  grade text not null, subject text not null, title text not null,
  description text, difficulty text, duration_sec int, question_count int, total_marks int,
  created_at timestamptz default now(), updated_at timestamptz default now()
);
create table if not exists quiz_questions (
  id text primary key,
  quiz_id text references quizzes(id) on delete cascade,
  seq int not null, prompt text not null, options text[] not null,
  correct_index int not null, explanation text, marks int default 1
);
create table if not exists quiz_attempts (
  id uuid primary key default gen_random_uuid(),
  quiz_id text references quizzes(id) on delete cascade,
  school_id uuid references schools(id) on delete cascade,
  student_id text, student_name text,
  score int, total int, percent int, badge text, duration_sec int,
  taken_at timestamptz default now()
);

alter table syllabus enable row level security;
alter table study_materials enable row level security;
alter table quizzes enable row level security;
alter table quiz_questions enable row level security;
alter table quiz_attempts enable row level security;
do $$ begin
  perform 1;
  begin create policy p_read on syllabus for select to authenticated using (true); exception when duplicate_object then null; end;
  begin create policy p_read on study_materials for select to authenticated using (true); exception when duplicate_object then null; end;
  begin create policy p_read on quizzes for select to authenticated using (true); exception when duplicate_object then null; end;
  begin create policy p_read on quiz_questions for select to authenticated using (true); exception when duplicate_object then null; end;
  begin create policy p_rw on quiz_attempts for all to authenticated using (true) with check (true); exception when duplicate_object then null; end;
end $$;

